"""Original multivariable constructions; installed by coverage.py. No third-party expressions copied."""
import sympy as s
x,y,z,t=s.symbols('x y z t',real=True)
R=s.Rational

def install(core):
 register,proof,latex,text=map(core.__getitem__,['register','proof','latex','text'])
 equal=core['equal']
 def p(Q,A,W,steps,checks,shape,domain=(),route='exact-multivariable-symbolic-certificate'):
  return proof(Q,A,[(v,why) for v,why in zip(W,['omit a geometric or derivative contribution','use an incorrect constraint or normalization','choose an invalid branch or boundary'])],[text(v) if isinstance(v,str) else v for v in steps],checks,list(domain),route,shape)
 def add(level,slug,group,method,builder,why):register('multivariable',level,slug,group,method,'local computation' if level=='easy' else 'geometric synthesis',why,builder,fit='candidate')
 def at(expr,values):return s.simplify(expr.subs(values,simultaneous=True))
 def grad(f):return s.Matrix([s.diff(f,x),s.diff(f,y)])
 def surface(m):
  F=x*x+y*y+z*z; normal=s.Matrix([s.diff(F,v) for v in (x,y,z)]).subs({x:1,y:1,z:m})
  return p(text('For the sphere ')+r'x^2+y^2+z^2='+latex(m*m+2)+text(', the tangent plane at ')+r'(1,1,'+latex(m)+r')'+text(' is ')+r'x+y+'+latex(m)+r'z=c.'+text(' Find c.'),m*m+2,[m*m,m+2,2*m*m+4],['The normal vector is proportional to (1,1,m). Substitute the point into the plane.'],[equal(normal,s.Matrix([2,2,2*m])),equal(1+1+m*m,m*m+2)],'sphere-tangent-plane-offset',['m is the displayed fixed integer.'])
 add('easy','partial-hold-fixed','partial-derivative','hold-other-variable-fixed',lambda m:p(r'f(x,y)=x^2y+y^3.\quad f_x('+latex(m)+r',1)=?',2*m,[m*m+3,2*m+3,m*m],['Treat y as a constant while differentiating in x.'],[equal(at(s.diff(x*x*y+y**3,x),{x:m,y:1}),2*m)],'single-partial-polynomial'),'Distinguishes partial differentiation from varying both coordinates.')
 add('easy','mixed-partial','mixed-second-partial','successive-partials',lambda m:p(r'f(x,y)=x^2y^{'+latex(m)+r'}.\quad f_{xy}(1,1)=?',2*m,[m,2*m*(m-1),2],['Differentiate once in each indicated variable.'],[equal(at(s.diff(x*x*y**m,x,y),{x:1,y:1}),2*m)],'mixed-partial-monomial'),'Tracks which variable each differentiation acts on.')
 add('easy','directional-unit','normalized-direction','directional-derivative',lambda m:p(r'f(x,y)=x^2+y^2.\quad D_{(3/5,4/5)}f('+latex(m)+r',0)=?',6*m/5,[3*m,2*m,8*m/5],['Dot the gradient with the supplied unit vector.'],[equal((grad(x*x+y*y).dot(s.Matrix([R(3,5),R(4,5)]))).subs({x:m,y:0}),6*m/5)],'directional-unit-vector'),'Uses a normalized direction rather than a coordinate derivative.')
 add('easy','tangent-plane','tangent-plane','gradient-normal',surface,'Uses a level surface gradient to determine a tangent plane.')
 add('easy','linearization-two-inputs','total-differential','linearization',lambda m:p(text('Use linearization of ')+r'f(x,y)=xy'+text(' at ')+r'('+latex(m)+r',2)'+text(' to estimate ')+r'f('+latex(m+R(1,10))+r',2.1).',2*m+(m+2)/10,[2*m+(m+2)/10+R(1,100),2*m+m/10,2*m+R(1,5)],['The linear increment is f_x times 0.1 plus f_y times 0.1; discard the quadratic increment.'],[equal(2*m+at(grad(x*y).dot(s.Matrix([R(1,10),R(1,10)])),{x:m,y:2}),2*m+(m+2)/10)],'two-variable-linear-approximation'),'Adds both first-order coordinate effects and excludes the cross error.')
 add('easy','rectangle-integral','double-integral-separable','iterated-integration',lambda m:p(r'\int_0^1\int_0^{'+latex(m)+r'}(x+y)\,dy\,dx',m*(m+1)/2,[m*m/2,m*(m+1),m+1],['Integrate the inner variable over its own interval, then the outer variable.'],[equal(s.integrate(x+y,(y,0,m),(x,0,1)),m*(m+1)/2)],'rectangular-double-integral'),'Interprets order and limits in a rectangular integral.')
 add('easy','triangular-region','triangle-iterated-area','variable-boundary',lambda m:p(r'\int_0^{'+latex(m)+r'}\int_0^{'+latex(m)+r'-x}1\,dy\,dx',m*m/2,[m*m,m/2,2*m*m],['The region is a right triangle; the upper inner bound depends on x.'],[equal(s.integrate(1,(y,0,m-x),(x,0,m)),m*m/2)],'triangle-area-double-integral'),'Reads a nonrectangular domain from variable limits.')
 add('easy','polar-area','polar-Jacobian','polar-coordinates',lambda m:p(r'\iint_{x^2+y^2\le '+latex(m*m)+r'}1\,dA',s.pi*m*m,[s.pi*m,s.pi*m*m/2,s.pi*m**3],['In polar coordinates dA=r dr dtheta.'],[equal(s.integrate(t,(t,0,m))*2*s.pi,s.pi*m*m)],'disk-area-polar'),'Includes the radial Jacobian in a change of coordinates.')
 add('easy','chain-curve','multivariable-chain-rule','curve-derivative',lambda m:p(r'f(x,y)=x^2+y^2,\quad (x(t),y(t))=(t,t^2).\quad \frac{d}{dt}f(x(t),y(t))\big|_{t='+latex(m)+r'}=?',2*m+4*m**3,[2*m+2*m*m,2*m,4*m**3],['Both coordinates vary along the curve; include both chain-rule contributions.'],[equal(s.diff(t*t+t**4,t).subs(t,m),2*m+4*m**3)],'curve-composition-total-derivative'),'Connects a scalar field to a parameterized path.')
 add('easy','divergence','divergence-trace','sum-coordinate-derivatives',lambda m:p(r'\mathbf F=(x^2,xy,'+latex(m)+r'z).\quad (\nabla\cdot\mathbf F)(1,1,1)=?',m+3,[m+2,m+4,2*m+1],['Divergence sums only the matching coordinate derivatives.'],[equal((s.diff(x*x,x)+s.diff(x*y,y)+s.diff(m*z,z)).subs({x:1,y:1,z:1}),m+3)],'divergence-polynomial-field'),'Selects the correct derivative from each vector component.')
 add('easy','potential-endpoints','gradient-line-integral','fundamental-theorem-line-integrals',lambda m:p(r'\mathbf F=\nabla(x^2+y^2).\quad \int_{(0,0)}^{('+latex(m)+r',1)}\mathbf F\cdot d\mathbf r=?',m*m+1,[m*m-1,2*m+2,0],['A gradient field accumulates the potential difference, independent of the smooth path.'],[equal((x*x+y*y).subs({x:m,y:1})-(x*x+y*y).subs({x:0,y:0}),m*m+1)],'conservative-field-endpoint-data',['Any piecewise smooth path with the stated endpoints.']),'Uses a potential instead of parameterizing an arbitrary path.')
 add('easy','box-average','multivariate-average','volume-normalization',lambda m:p(text('Find the average of ')+r'f(x,y,z)=x+y+z'+text(' on ')+r'[0,'+latex(m)+r']\times[0,1]\times[0,2].',m/2+R(3,2),[m+3,m/2+1,m*(m+3)],['Divide the triple integral by box volume 2m.'],[equal(s.integrate(x+y+z,(x,0,m),(y,0,1),(z,0,2))/(2*m),m/2+R(3,2))],'box-average-value'),'Distinguishes integral from mean value in three dimensions.')

 add('medium','gradient-max-direction','steepest-ascent','Cauchy-Schwarz',lambda m:p(r'f(x,y)=e^{x+2y}.\quad\max_{\|u\|=1}D_u f(\log '+latex(m)+r',0)=?',m*s.sqrt(5),[3*m,5*m,m],['The greatest directional derivative is the Euclidean norm of the gradient. Equality uses its unit direction.'],[equal(grad(s.exp(x+2*y)).subs({x:s.log(m),y:0}).dot(grad(s.exp(x+2*y)).subs({x:s.log(m),y:0})),5*m*m)],'maximum-directional-derivative'),'Uses an optimization principle after computing the gradient.')
 add('medium','quadratic-critical-value','positive-definite-quadratic','complete-square',lambda m:p(text('Find the minimum over real x,y of ')+latex((x+y-m)**2+2*(x-y-1)**2),0,[m*m+2,-m*m,1],['Both squares vanish at x=(m+1)/2,y=(m-1)/2. Their nonnegativity proves global minimality.'],[equal(at((x+y-m)**2+2*(x-y-1)**2,{x:(m+1)/2,y:(m-1)/2}),0)],'two-square-global-minimum'),'Checks attainable equality as well as a nonnegative lower bound.')
 add('medium','Lagrange-circle-linear','linear-circle-extremum','Lagrange-multipliers',lambda m:p(r'\max_{x^2+y^2=1}('+latex(m)+r'x+y)=?',s.sqrt(m*m+1),[m+1,m*m+1,m],['The maximum equals the coefficient-vector norm; the maximizing point is parallel to (m,1).'],[equal((m/s.sqrt(m*m+1))**2+(1/s.sqrt(m*m+1))**2,1),equal(m*m/s.sqrt(m*m+1)+1/s.sqrt(m*m+1),s.sqrt(m*m+1))],'linear-form-circle-constraint'),'Solves a constrained extremum and verifies equality conditions.')
 add('medium','change-order','reversed-integral-region','Fubini-region-reconstruction',lambda m:p(r'\int_0^1\int_x^1 '+latex(m)+r'y^{'+latex(m-1)+r'}\,dy\,dx',m/(m+1),[1,1/(m+1),(m-1)/m],['Reversing the triangle gives 0<y<1,0<x<y, so the integral is m times integral y^m.'],[equal(s.integrate(m*y**(m-1),(y,x,1),(x,0,1)),m/(m+1)),equal(s.integrate(m*y**(m-1),(x,0,y),(y,0,1)),m/(m+1))],'reverse-triangular-integration-order'),'Uses region reconstruction to simplify an iterated integral.')
 add('medium','ellipse-transform','affine-Jacobian','linear-change-variables',lambda m:p(r'\iint_{x^2/'+latex(m*m)+r'+y^2\le1}1\,dA',s.pi*m,[s.pi*m*m,s.pi/m,2*s.pi*m],['Set x=mu,y=v; the unit disk scales area by determinant m.'],[equal(s.Matrix([[s.diff(m*x,x),0],[0,1]]).det(),m)],'ellipse-area-linear-Jacobian'),'Accounts for the determinant of an affine transformation.')
 add('medium','polar-moment','polar-moment','polar-coordinates',lambda m:p(r'\iint_{x^2+y^2\le1}(x^2+y^2)^{'+latex(m)+r'}\,dA',s.pi/(m+1),[s.pi/(2*m+1),2*s.pi/(m+1),s.pi/m],['The integrand is r^(2m), and area contributes another r.'],[equal(2*s.pi*s.integrate(t**(2*m+1),(t,0,1)),s.pi/(m+1))],'radial-disk-moment'),'Combines a radial power with the area Jacobian.')
 add('medium','Green-circulation','Green-theorem','curl-to-area',lambda m:p(r'C:\ x^2+y^2='+latex(m*m)+text(', counterclockwise. Find ')+r'\oint_C(-y\,dx+x\,dy).',2*s.pi*m*m,[s.pi*m*m,-2*s.pi*m*m,2*s.pi*m],['The planar curl is 2; Green theorem gives twice the disk area.'],[equal(s.diff(x,x)-s.diff(-y,y),2),equal(s.integrate(((-m*s.sin(t))*(-m*s.sin(t))+(m*s.cos(t))*(m*s.cos(t))),(t,0,2*s.pi)),2*s.pi*m*m)],'circulation-Green-disk'),'Chooses Green theorem and respects orientation.')
 add('medium','divergence-flux','divergence-theorem','volume-integral',lambda m:p(text('Find outward flux of ')+r'\mathbf F=(x,y,z)'+text(' through the sphere ')+r'x^2+y^2+z^2='+latex(m*m)+'.',4*s.pi*m**3,[4*s.pi*m*m,R(4,3)*s.pi*m**3,12*s.pi*m**3],['Divergence is 3. Multiply it by ball volume 4 pi m cubed over three.'],[equal(s.diff(x,x)+s.diff(y,y)+s.diff(z,z),3),equal(3*s.integrate(4*s.pi*t*t,(t,0,m)),4*s.pi*m**3)],'radial-field-sphere-flux'),'Converts a surface flux into a volume integral.')
 add('medium','surface-graph-area','graph-surface-area','cross-product-Jacobian',lambda m:p(text('Find area of ')+r'z='+latex(m)+r'x+y'+text(' above the unit square.'),s.sqrt(m*m+2),[m+2,s.sqrt(m*m+1),m*m+2],['The graph area density is sqrt(1+z_x squared+z_y squared), constant here.'],[equal(s.Matrix([1,0,m]).cross(s.Matrix([0,1,1])).dot(s.Matrix([1,0,m]).cross(s.Matrix([0,1,1]))),m*m+2)],'planar-graph-surface-area'),'Separates projected area from actual surface area.')
 add('medium','implicit-surface-partial','implicit-surface-differentiation','implicit-function-theorem',lambda m:p(r'x^2+y^2+z^2='+latex(m*m+2)+r'.\quad z_x(1,1)\textnormal{ on the branch }z(1,1)='+latex(m)+r'=?',-1/m,[1/m,-m,0],['Differentiate with y fixed: 2x+2z z_x=0. The z derivative of the constraint is nonzero.'],[equal(s.diff(s.sqrt(m*m+2-x*x-y*y),x).subs({x:1,y:1}),-1/m)],'implicit-sphere-partial',['The positive branch is smooth near (1,1).']),'Uses a nonzero partial derivative to justify solving locally.')
 add('medium','density-centroid','weighted-centroid','moment-normalization',lambda m:p(text('A lamina on the unit square has density ')+r'\rho(x,y)=x^{'+latex(m)+r'}.\quad \bar x=?',(m+1)/(m+2),[1/(m+2),(m+2)/(m+1),R(1,2)],['Divide the x moment by total mass; the y integrals cancel.'],[equal(s.integrate(x**(m+1),(x,0,1))/s.integrate(x**m,(x,0,1)),(m+1)/(m+2))],'density-weighted-centroid'),'Weights position by a nonuniform density before normalization.')
 add('medium','spherical-moment','spherical-coordinates','radial-volume-Jacobian',lambda m:p(r'\iiint_{x^2+y^2+z^2\le1}(x^2+y^2+z^2)^{'+latex(m)+r'}\,dV',4*s.pi/(2*m+3),[4*s.pi/(2*m+1),2*s.pi/(m+1),s.pi/(2*m+3)],['The three-dimensional volume Jacobian adds r squared; the angular integral is 4 pi.'],[equal(4*s.pi*s.integrate(t**(2*m+2),(t,0,1)),4*s.pi/(2*m+3))],'ball-radial-power-moment'),'Requires the three-dimensional radial measure, distinct from disk area.')

 add('hard','quadratic-eigenconstraint','Rayleigh-quotient','eigenvalue-optimization',lambda m:p(r'\max_{x^2+y^2=1}('+latex(m)+r'x^2+2xy+('+latex(m+1)+r')y^2)=?',m+R(1,2)+s.sqrt(5)/2,[m+1,m+R(1,2)-s.sqrt(5)/2,2*m+1],['The symmetric quadratic form has eigenvalues (2m+1 plus or minus sqrt5)/2. The largest is attained on its eigenvector.'],[equal((s.Matrix([[m,1],[1,m+1]])-(m+R(1,2)+s.sqrt(5)/2)*s.eye(2)).det(),0)],'symmetric-quadratic-on-circle'),'A coupled quadratic constraint leads to a spectral rather than coordinate maximum.')
 add('hard','moving-domain-derivative','Reynolds-transport','differentiate-transformed-domain',lambda m:p(r'I(a)=\iint_{x^2+y^2\le a^2}e^{x^2+y^2}\,dA,\ a>0.\quad I\prime('+latex(m)+r')=?',2*s.pi*m*s.exp(m*m),[s.pi*s.exp(m*m),2*s.pi*s.exp(m*m),4*s.pi*m*m*s.exp(m*m)],['First use polar coordinates to write I(a)=pi(exp(a squared)-1). Then differentiate the moving boundary.'],[equal(s.diff(s.pi*(s.exp(t*t)-1),t).subs(t,m),2*s.pi*m*s.exp(m*m))],'moving-disk-boundary-integral'),'The domain moves; treating only the integrand derivative would give zero.')
 add('hard','ellipsoid-inertia','ellipsoid-second-moment','affine-transform-and-symmetry',lambda m:p(r'\iiint_{x^2/'+latex(m*m)+r'+y^2+z^2\le1}x^2\,dV',4*s.pi*m**3/15,[4*s.pi*m/15,4*s.pi*m**3/5,4*s.pi*m**3/3],['Scale x=mu. Symmetry gives one third of the unit ball radial second moment, and the Jacobian contributes m.'],[equal(m**3*R(1,3)*4*s.pi*s.integrate(t**4,(t,0,1)),4*s.pi*m**3/15)],'ellipsoid-axis-second-moment'),'Combines a nonspherical transform, density scaling, and rotational symmetry.')
 add('hard','nonlinear-Jacobian','hyperbolic-coordinate-change','nonlinear-change-variables',lambda m:p(text('Let D be x,y>0 with ')+r'1\le xy\le '+latex(m)+r',\quad1\le x/y\le e^2.'+text(' Find its area.'),m-1,[2*(m-1),s.log(m),m*m-1],['Use u=xy,v=x/y. Then x=sqrt(uv),y=sqrt(u/v), and absolute Jacobian is 1/(2v).'],[equal(abs(s.Matrix([s.sqrt(x*y),s.sqrt(x/y)]).jacobian([x,y]).det()).subs({x:m,y:m}),1/(2*m)),equal(s.integrate(1/(2*y),(y,1,s.exp(2)),(x,1,m)),m-1)],'product-ratio-positive-quadrant',['Use the positive branch, one-to-one on the positive quadrant.']),'A nonlinear mapping turns hyperbolic boundaries into a rectangle.')
 add('hard','simplex-beta','Dirichlet-simplex-moment','iterated-beta-integral',lambda m:p(r'\iint_{x,y\ge0,\ x+y\le1}x^{'+latex(m)+r'}y^{'+latex(m+1)+r'}\,dA',s.factorial(m)*s.factorial(m+1)/s.factorial(2*m+3),[s.factorial(m)*s.factorial(m+1)/s.factorial(2*m+2),s.factorial(m+1)**2/s.factorial(2*m+3),s.factorial(m)*s.factorial(m+1)/s.factorial(2*m+4)],['Integrate in y first. The remaining beta integral has endpoint exponents m and m+2.'],[equal(s.integrate(s.expand(x**m*(1-x)**(m+2)/(m+2)),(x,0,1)),s.factorial(m)*s.factorial(m+1)/s.factorial(2*m+3))],'polynomial-simplex-beta'),'Two integrations interact through a sloping boundary and factorial indices.')
 add('hard','nonconservative-hole','closed-nonexact-field','winding-number',lambda m:p(r'C(t)=('+latex(m)+r'\cos t,'+latex(m)+r'\sin t),\ 0\le t\le2\pi.\quad\oint_C\frac{-y\,dx+x\,dy}{x^2+y^2}=?',2*s.pi,[0,s.pi*m*m,2*s.pi*m],['Parameterize the circle. The integrand becomes dt. The field is undefined at the origin, so zero local curl does not imply a global potential.'],[equal(s.trigsimp((m*m*s.sin(t)**2+m*m*s.cos(t)**2)/(m*m)),1)],'closed-field-nonsimply-connected-domain',['The circle avoids the origin.']),'Uses topology to diagnose a false application of Green theorem.')
 add('hard','Stokes-tilted-surface','Stokes-theorem','boundary-surface-conversion',lambda m:p(text('C is the boundary of ')+r'z='+latex(m)+r'x+y,\ 0\le x,y\le1,'+text(' oriented by the upward normal. Find ')+r'\oint_C(-y\,dx+x\,dy+z\,dz).',2,[0,2*s.sqrt(m*m+2),2*m],['Curl(-y,x,z)=(0,0,2). Dot with the oriented graph area vector (-m,-1,1)dxdy.'],[equal(s.Matrix([s.diff(z,y)-s.diff(x,z),s.diff(-y,z)-s.diff(z,x),s.diff(x,x)-s.diff(-y,y)]).dot(s.Matrix([-m,-1,1])),2)],'Stokes-tilted-graph-curl-flux'),'The surface area factor cancels through the vector area element; orientation is decisive.')
 add('hard','boundary-versus-interior','constrained-boundary-extrema','boundary-critical-analysis',lambda m:p(r'\max_{0\le x,y\le1}\big('+latex(m)+r'xy-x^2-y^2\big)=?',m-2,[0,m/2-1,m],['For m>=4, fixing x makes a concave quadratic in y. Check its clipped optimizer and all boundary critical points; (1,1) gives the maximum.'],[equal(m*x*y-x*x-y*y, (m-2)*x*y-(x-y)**2),bool(m-2>0)],'square-domain-coupled-quadratic',['Since xy<=1 and the square is nonnegative, f<=(m-2); equality occurs at (1,1).']),'A global algebraic bound proves boundary optimality without relying on interior stationary points.')
 add('hard','surface-flux-graph','oriented-graph-flux','normal-area-vector',lambda m:p(text('Find upward flux of ')+r'\mathbf F=(x,y,z)'+text(' through ')+r'z=1-x^2-y^2,\ x^2+y^2\le '+latex(1/m)+'.',s.pi/m+s.pi/(2*m*m),[s.pi/m-s.pi/(2*m*m),s.pi/m,s.pi/(2*m*m)],['The area vector is (2x,2y,1)dxdy, so F dot dS=(1+x squared+y squared)dA. Integrate over the disk.'],[equal(s.Matrix([x,y,1-x*x-y*y]).dot(s.Matrix([2*x,2*y,1])),1+x*x+y*y),equal(2*s.pi*s.integrate((1+t*t)*t,(t,0,s.sqrt(1/m))),s.pi/m+s.pi/(2*m*m))],'paraboloid-oriented-flux'),'Combines a nonconstant normal with a curved graph and polar integration.')
 add('hard','mixed-Hessian-coordinate','Hessian-under-rotation','second-order-chain-rule',lambda m:p(r'f(x,y)=x^2+'+latex(m)+r'y^2,\quad x=u+v,\ y=u-v.\quad\partial_{uv}f=?',2-2*m,[2+2*m,1-m,0],['Transform the quadratic first or use the Hessian congruence J transpose H J; read its off-diagonal entry.'],[equal(s.diff((x+y)**2+m*(x-y)**2,x,y),2-2*m)],'Hessian-coordinate-congruence'),'A mixed partial appears even though the original quadratic is diagonal.')
 add('hard','path-dependent-directional','multivariable-limit-paths','curved-path-test',lambda m:p(r'f(x,y)=\frac{x^{'+latex(m)+r'}y}{x^{'+latex(2*m)+r'}+y^2},\quad(x,y)\ne(0,0).'+text(' What is its limit along y=x^m as x tends to zero through positive values?'),R(1,2),[0,1,R(1,4)],['Substitute the curved path before cancelling. Coordinate-axis limits are zero and therefore do not determine the full limit.'],[equal((x**m*y/(x**(2*m)+y*y)).subs(y,x**m),R(1,2))],'anisotropic-path-limit',['x>0 on the specified path.']),'A curved approach exposes behavior hidden from coordinate axes.')
 add('hard','Gaussian-precision','Gaussian-positive-form','complete-square-Gaussian',lambda m:p(r'\iint_{\mathbb R^2}e^{-('+latex(m)+r'x^2+2xy+y^2)}\,dx\,dy',s.pi/s.sqrt(m-1),[s.pi/s.sqrt(m),s.pi/(m-1),2*s.pi/s.sqrt(m-1)],['Complete the square: mx squared+2xy+y squared=(y+x)^2+(m-1)x squared. The shear has determinant one; multiply two Gaussian integrals.'],[equal(m*x*x+2*x*y+y*y,(y+x)**2+(m-1)*x*x),bool(m-1>0)],'coupled-two-dimensional-Gaussian',['m>1 ensures a positive-definite quadratic form.'],'square-completion-and-Gaussian-theorem'),'A coupled quadratic requires positivity and a change of variables before separating integrals.')

 # Advanced constructions include nontrivial global/geometric reasoning; audit may quarantine any rating.
 add('olympiad','Vandermonde-extremum','discriminant-constraint','symmetric-invariant-optimization',lambda m:discriminant(m,p,latex,text,equal),'Reframes a constrained sixth-degree optimization as a cubic discriminant with an attainable sharp bound.')
 add('olympiad','anisotropic-integrability','anisotropic-singularity','two-scale-integrability',lambda m:singularity(m,p,latex,text,equal),'Requires resolving a singularity whose natural scales differ by a power; straight polar estimates are insufficient.')
 add('olympiad','Gaussian-wedge','correlated-Gaussian-orthant','whitening-and-angular-domain',lambda m:wedge(m,p,latex,text,equal),'A coupled Gaussian on a quadrant becomes an oblique wedge; determining its angle is part of the calculation.')
 add('olympiad','planar-log-potential','logarithmic-potential','harmonic-circle-mean',lambda m:logpotential(m,p,latex,text,equal),'Splits radial shells at an interior singularity, applying the harmonic mean on the correct side of that radius.')
 add('olympiad','two-centre-resolvent','Feynman-parameter-integral','parameterization-and-translation',lambda m:resolvent(m,p,latex,text,equal),'Introduces an auxiliary parameter to combine shifted denominators, then integrates a nontrivial exact parameter integral.')
 add('olympiad','simplex-log-partition','entropy-Legendre-duality','strict-convexity-and-gradient-inversion',lambda m:entropy(m,p,latex,text,equal),'An unconstrained nonlinear minimum is solved through probability coordinates, with strict convexity establishing uniqueness.')
