def discriminant(m,p,L,T,E):
 V=(x-y)**2*(y-z)**2*(z-x)**2; q=x*y*z
 # Substitute z=-x-y to enforce sum zero. For cubic roots, discriminant identity is exact.
 identity=E(V.subs(z,-x-y),((x*x+y*y+z*z)**3/2-27*q*q).subs(z,-x-y))
 return p(r'x+y+z=0,\ x^2+y^2+z^2='+L(m)+r'.\quad\max (x-y)^2(y-z)^2(z-x)^2=?',m**3/2,[m**3,m**3/4,m*m/2],['The cubic with these three roots is t cubed-(m/2)t-xyz. Its discriminant is m cubed/2-27(xyz)^2.','The upper bound is attained at (sqrt(m/2),0,-sqrt(m/2)).'],[identity,E(V.subs({x:s.sqrt(m/2),y:0,z:-s.sqrt(m/2)}),m**3/2)],'Vandermonde-discriminant-sphere-extremum',['Real triples; the constraint set is compact.'])

def singularity(m,p,L,T,E):
 a=s.symbols('a',real=True); u=s.symbols('u',positive=True)
 return p(r'I(\alpha)=\int_0^1\int_0^1\frac{x^\alpha}{x^2+y^{'+L(2*m)+r'}}\,dy\,dx.'+T(' There is a sharp threshold c such that I(alpha) is finite exactly for alpha>c. Find c.'),1-1/m,[1,1/m,1+1/m],['For fixed x>0, set y=x^(1/m)t. The integral becomes integral x^(alpha+1/m-2) times J(x), where J(x)=integral_0^(x^-1/m)1/(1+t^(2m))dt.','For 0<x<=1, J is bounded below by 1/2 and above by 1+1/(2m-1). Hence convergence is exactly alpha+1/m-2>-1. The endpoint diverges logarithmically.'],[E((u**a/(u*u+(u**(1/m)*t)**(2*m))*u**(1/m)).subs(t,s.Symbol('v',positive=True)),(u**(a+1/m-2)/(1+s.Symbol('v',positive=True)**(2*m)))),E(s.solve(a+1/m-2+1,a)[0],1-1/m),bool(2*m>1)],'anisotropic-integrability-threshold',['All integrands nonnegative; Tonelli permits the iterated substitution.','On t>=1, 1/(1+t^(2m))<=t^(-2m); on [0,1] it is at least 1/2.'],'two-sided-integral-comparison-with-exact-Jacobian')

def wedge(m,p,L,T,E):
 theta=s.pi/m; rho=s.cos(theta); A=s.pi*(m-1)/(2*m*s.sin(theta))
 # u=x-rho*y,v=sin(theta)*y; positive x,y maps to v>0,u>-cot(theta)v.
 return p(r'\int_0^\infty\int_0^\infty\exp\left[-x^2+2\cos('+L(theta)+r')xy-y^2\right]\,dx\,dy',A,[s.pi/(4*s.sin(theta)),s.pi/(2*m*s.sin(theta)),s.pi*(m-1)/(m*s.sin(theta))],['Whiten with u=x-cos(theta)y, v=sin(theta)y. The exponent becomes -(u squared+v squared), and dxdy=dudv/sin(theta).','The positive quadrant maps to the wedge 0<arg(u+iv)<pi-theta. Its radial Gaussian integral is one half.'],[E(s.expand((x-rho*y)**2+(s.sin(theta)*y)**2).expand(trig=True).simplify(),x*x-2*rho*x*y+y*y),E(s.Matrix([x-rho*y,s.sin(theta)*y]).jacobian([x,y]).det(),s.sin(theta)),E(s.integrate(t*s.exp(-t*t),(t,0,s.oo))*(s.pi-theta)/s.sin(theta),A)],'correlated-Gaussian-positive-quadrant',['0<theta<=pi/4; the Jacobian and quadratic form are positive.'],'linear-map-angular-domain-and-Gaussian-certificate')

def logpotential(m,p,L,T,E):
 a=1/m; A=s.pi*(a*a-1)/2
 return p(r'\iint_{x^2+y^2\le1}\log\sqrt{(x-'+L(a)+r')^2+y^2}\,dA',A,[-s.pi/2,s.pi*(a*a+1)/2,s.pi*(a-1)/2],['The mean of log|r exp(i theta)-a| around a circle is log max(r,a). For r<a factor out a, and for r>a factor out r; the remaining harmonic logarithm has mean zero.','Split the radial integral at r=a. The point singularity is locally integrable because integral_0^epsilon r|log r|dr is finite.'],[E(2*s.pi*(s.integrate(t*s.log(a),(t,0,a))+s.integrate(t*s.log(t),(t,a,1))),A),E(s.limit(t*t*s.log(t),t,0,dir='+'),0)],'disk-logarithmic-potential-interior-source',['0<a<1; use the harmonic mean theorem on circles not through the source.'],'harmonic-circle-mean-and-exact-radial-certificate')

def resolvent(m,p,L,T,E):
 A=4*s.pi*s.atanh(m/s.sqrt(m*m+4))/(m*s.sqrt(m*m+4))
 u=s.symbols('u',positive=True); c=1+m*m*u*(1-u)
 F=2/(m*s.sqrt(m*m+4))*s.atanh(m*(2*u-1)/s.sqrt(m*m+4))
 # note sign derivative positive; F'=1/c
 return p(r'\iint_{\mathbb R^2}\frac{dx\,dy}{(1+x^2+y^2)(1+(x-'+L(m)+r')^2+y^2)}',A,[A/2,2*A,s.pi/(1+m*m)],['Use 1/(AB)=integral_0^1[ uA+(1-u)B ]^-2 du, valid for positive A,B. Complete the square in x.','For fixed u, translate to a radial integral pi/[1+m squared u(1-u)]. Its exact antiderivative is an inverse hyperbolic tangent.'],[E(s.diff(F,u),1/c),E(s.pi*(F.subs(u,1)-F.subs(u,0)),A),E(u*(1+x*x+y*y)+(1-u)*(1+(x-m)**2+y*y),(x-(1-u)*m)**2+y*y+c)],'two-translated-resolvent-plane-integral',['Tonelli applies to the nonnegative parameter integrand; c>=1.'],'Feynman-parameter-square-completion-antiderivative')

def entropy(m,p,L,T,E):
 a=1/m;b=2/m;c=1-a-b; xx=s.log(a/c); yy=s.log(b/c)
 f=s.log(1+s.exp(x)+s.exp(y))-a*x-b*y; A=-a*s.log(a)-b*s.log(b)-c*s.log(c)
 return p(r'\inf_{x,y\in\mathbb R}\left[\log(1+e^x+e^y)-\frac{x+2y}{'+L(m)+r'}\right]',A,[-A,-a*s.log(a)-b*s.log(b),s.log(m)],['At a critical point the normalized weights e^x/Z and e^y/Z must be 1/m and 2/m. The remaining weight is 1-3/m>0.','The Hessian is the covariance matrix of three noncollinear support points with positive weights, hence positive definite. The critical point is the unique global minimum.'],[E(s.diff(f,x).subs({x:xx,y:yy}),0),E(s.diff(f,y).subs({x:xx,y:yy}),0),E(s.expand_log(f.subs({x:xx,y:yy})-A,force=True),0),E(s.det(s.hessian(s.log(1+s.exp(x)+s.exp(y)),(x,y))),s.exp(x+y)/(1+s.exp(x)+s.exp(y))**3)],'log-sum-exp-Legendre-minimum',['m>=4 makes all three target weights strictly positive.'])

def lpball(m,p,L,T,E):
 n=int(m); A=2**m*s.gamma(1+1/m)**m
 return p(T('In ')+r'\mathbb R^{'+L(m)+r'},\quad'+T('find the volume of ')+r'\left\{(x_1,\ldots,x_'+L(m)+r'): \sum_{j=1}^{'+L(m)+r'}|x_j|^{'+L(m)+r'}\le1\right\}.',A,[A/s.factorial(m),2**m*s.gamma(1/m)**m,A/2],['In each orthant set u_j=|x_j|^m. The Jacobian density is m^-m product u_j^(1/m-1).','The simplex Dirichlet integral is Gamma(1/m)^m/Gamma(2), since the exponents sum to one. Multiply by all 2^m orthants and use Gamma(1+1/m)=Gamma(1/m)/m.'],[E(s.diff(t**(1/m),t),t**(1/m-1)/m),E(s.expand_func(2**m*s.gamma(1/m)**m/(m**m*s.gamma(2))),s.expand_func(A))],'dimension-equals-power-lp-ball',['Integer dimension m>=4; all Dirichlet exponents are positive.'],'Dirichlet-integral-positive-parameters-and-Jacobian')

def gaussianmoment(m,p,L,T,E):
 # Integral x^(2m) exp(-x²-2xy-2y²) dxdy. Integrating y gives sqrt(pi/2) exp(-x²/2).
 A=s.pi*s.factorial(2*m)/(2**m*s.factorial(m))
 return p(r'\iint_{\mathbb R^2}x^{'+L(2*m)+r'}e^{-x^2-2xy-2y^2}\,dx\,dy',A,[A/2**m,A*2**m,A/s.factorial(m)],['Complete the square: x squared+2xy+2y squared=2(y+x/2)^2+x squared/2.','The y Gaussian contributes sqrt(pi/2). The even x moment at variance one is sqrt(2pi)(2m)!/(2^m m!), obtained by differentiating the Gaussian integral m times.'],[E(x*x+2*x*y+2*y*y,2*(y+x/2)**2+x*x/2),E(s.sqrt(s.pi/2)*2**(m+R(1,2))*s.gamma(m+R(1,2)),A)],'high-even-moment-coupled-Gaussian',['Absolute integrability follows from the positive quadratic form.'],'square-completion-Gamma-moment')

def logbarrier(m,p,L,T,E):
 # minimum 1/x+4/y+m²/z on simplex = (m+3)²; genuinely global inequality but lower-level audit applies.
 A=(m+3)**2
 return p(r'\min_{x,y,z>0,\ x+y+z=1}\left(\frac1x+\frac4y+\frac{'+L(m*m)+r'}z\right)',A,[(m*m+5)*3,m*m+5,(m+2)**2],['Cauchy gives (1/x+4/y+m squared/z)(x+y+z)>=(1+2+m)^2.','Equality requires x:y:z=1:2:m, a positive feasible triple.'],[E(1/(1/(m+3))+4/(2/(m+3))+m*m/(m/(m+3)),A),E((1+2+m)/(m+3),1)],'reciprocal-simplex-sharp-bound',['Positive coordinates ensure the weighted Cauchy inequality applies.'],'weighted-Cauchy-and-attainable-equality')

def laplacian(m,p,L,T,E):
 n=int(m); f=s.exp(-x*x-y*y); A=(-4)**m*s.factorial(m)
 actual=sum(s.binomial(m,j)*s.diff(f,x,2*j,y,2*(n-j)).subs({x:0,y:0}) for j in range(n+1))
 return p(r'\Delta=\partial_x^2+\partial_y^2.\quad (\Delta^{'+L(m)+r'}e^{-x^2-y^2})(0,0)=?',A,[(-4)**m,(-2)**m*s.factorial(m),(-4)**m*s.factorial(m+1)],['For r squared=x squared+y squared, Delta(r^(2j))=4j squared r^(2j-2).','Only the j=m Taylor term of exp(-r squared) survives evaluation at the origin after m Laplacians. Its coefficient is (-1)^m/m!, giving (-4)^m m!.'],[E(actual,A),E(s.diff((x*x+y*y)**m,x,2)+s.diff((x*x+y*y)**m,y,2),4*m*m*(x*x+y*y)**(m-1))],'iterated-radial-Laplacian-coefficient',['The exponential is entire, so finite-order termwise differentiation is valid.'])

def logsimplex(m,p,L,T,E):
 a,b=s.symbols('a b',positive=True); B=s.gamma(a)*s.gamma(b)/s.gamma(a+b+1)
 # alpha=m+1, beta=2. value beta * [(psi(alpha)-psi(alpha+beta+1))*(psi(beta)-psi(total))-trigamma(total)]
 A=( (s.harmonic(m)-s.harmonic(m+3))*(1-s.harmonic(m+3))-(s.pi**2/6-s.harmonic(m+3,2)) )/((m+1)*(m+2)*(m+3))
 actual=s.diff(B,a,b).subs({a:m+1,b:2})
 return p(r'\iint_{x,y>0,\ x+y<1}x^{'+L(m)+r'}y\log x\log y\,dA',A,[-A,A+ s.pi**2/(6*(m+1)*(m+2)*(m+3)),A*((m+1)*(m+2)*(m+3))],['For positive a,b, the simplex moment is Gamma(a)Gamma(b)/Gamma(a+b+1). Differentiate once in each parameter.','Use psi(n)=H_(n-1)-gamma and psi1(n)=pi squared/6-H_(n-1)^(2). Logarithmic factors are integrable under nearby positive powers.'],[E(s.expand_func(actual),A)],'mixed-logarithmic-simplex-moment',['H_n=sum_(j=1)^n 1/j; H_n^(2)=sum_(j=1)^n 1/j squared.','Parameters a=m+1,b=2 stay positive in a neighborhood.'],'differentiated-Dirichlet-integral-and-polygamma-recurrence')

def angular(m,p,L,T,E):
 # Whole plane integral 1/(1+m*x²+y²)^2 = pi/sqrt(m); difficult? quarantine rating later.
 A=s.pi/s.sqrt(m)
 return p(r'\iint_{\mathbb R^2}\frac{dx\,dy}{(1+'+L(m)+r'x^2+y^2)^2}',A,[s.pi/m,3*s.pi/s.sqrt(m),s.pi/s.sqrt(m+1)],['Set u=sqrt(m)x,v=y; the Jacobian is 1/sqrt(m). In polar coordinates the remaining radial integral is one half.'],[E(s.integrate(t/(1+t*t)**2,(t,0,s.oo))*2*s.pi/s.sqrt(m),A)],'anisotropic-plane-resolvent',['m>0; the integrand has integrable inverse-fourth-power decay.'],'linear-Jacobian-and-radial-antiderivative')

def advanced_replacements(core):
 """Additional independent advanced decisions; raw predecessors remain in audit catalogue."""
 P,E,L,T=map(core.__getitem__,['proof','equal','latex','text'])
 def p(Q,A,W,steps,checks,shape,domain=(),route='analytic-and-exact-symbolic-certificate'):
  return P(Q,A,[(v,why) for v,why in W],[T(v) for v in steps],checks,list(domain),route,shape)
 def add(slug,group,method,builder,why):core['register']('multivariable','olympiad',slug,group,method,'reframing and synthesis',why,builder,fit='candidate')
 def lemniscate(m):
  # Re(z^m)^2 etc displayed via complex modulus, exact polar geometry.
  A=2**(2/m-1)*s.sqrt(s.pi)*s.gamma(R(1,2)+1/m)/s.gamma(1+1/m)
  beta=s.beta(R(1,2),R(1,2)+1/m)
  actual=2**(2/m-1)*s.expand_func(beta)
  return p(T('Find the planar area of ')+r'\{z=x+iy\in\mathbb C:\ |z^{'+L(m)+r'}-1|\le1\}.',A,[(A/m,'count only one petal'),(2*A,'omit the polar radial factor one half'),(2**(1/m-1)*s.sqrt(s.pi)*s.gamma(R(1,2)+1/(2*m))/s.gamma(1+1/(2*m)),'use radius instead of squared radius')],['In polar coordinates the inequality reduces to r^m<=2cos(m theta), restricted to cosine-positive sectors. There are m identical petals.','Integrating r dr gives one half of (2cos(m theta))^(2/m). The m petals cancel the 1/m angular substitution factor.','The remaining cosine moment on [-pi/2,pi/2] equals Beta(1/2,1/2+1/m).'],[E((s.Symbol('r',nonnegative=True)**m*s.cos(m*t)-1)**2+(s.Symbol('r',nonnegative=True)**m*s.sin(m*t))**2-1,s.Symbol('r',nonnegative=True)**(2*m)-2*s.Symbol('r',nonnegative=True)**m*s.cos(m*t)),E(actual,A)],'complex-polynomial-lemniscate-area',['m>=4; each radial sector is star-shaped and the petals overlap only at the origin.','The beta exponents 1/2 and 1/2+1/m are positive.'],'polar-petal-decomposition-and-beta-moment')
 def logsquare(m):
  q=1/(m*m);A=s.pi/2*(s.polylog(2,q)+(1-1/q)*s.log(1-q)-1)
  n=s.symbols('n',integer=True,positive=True)
  return p(r'\iint_{x^2+y^2\le1}\left[\log\sqrt{(1-x/'+L(m)+r')^2+y^2/'+L(m*m)+r'}\right]^2\,dA'+r',\quad \operatorname{Li}_2(q)=\sum_{n=1}^\infty q^n/n^2.',A,[(2*A,'omit the cosine orthogonality factor'),(A/2,'apply the orthogonality factor twice'),(s.pi/2*(s.polylog(2,q)+(1+1/q)*s.log(1-q)-1),'wrong sign in shifted logarithm series')],['Write log|1-r exp(i theta)/m|=-sum (r/m)^n cos(n theta)/n. The series is uniformly absolutely convergent since r/m<=1/4.','Angular orthogonality removes all cross terms and gives pi times sum r^(2n)/(m^(2n)n squared). Radial integration adds 1/(2n+2).','Decompose 1/[n squared(n+1)]=1/n squared-1/n+1/(n+1) and sum using Li_2 and the logarithmic series.'],[E(1/(n*n*(n+1)),1/n**2-1/n+1/(n+1)),E(s.integrate(t**(2*n+1),(t,0,1)),1/(2*n+2)),E(s.pi/2*(s.polylog(2,q)+s.log(1-q)+(-s.log(1-q)-q)/q),A)],'disk-squared-log-harmonic-Parseval',['The zero of 1-z/m lies outside the disk; uniform convergence permits squaring and integration.'],'uniform-Fourier-expansion-orthogonality-and-series')
 def cusp(m):
  # Integral over xy<=1 weighted radial nonlinear exponent, regions split at diagonal via reciprocal scale.
  # Global volume under e^[-(x+y)^m] times x^(m-1)y on positive quadrant.
  A=s.gamma(1+2/m)/(m*m*(m+1))
  uu,vv=s.symbols('u v',positive=True)
  F=s.Matrix([uu*vv,uu*(1-vv)])
  return p(r'\int_0^\infty\int_0^\infty x^{'+L(m-1)+r'}y\,e^{-(x+y)^{'+L(m)+r'}}\,dx\,dy',A,[(m*A,'omit the power substitution Jacobian'),((m+1)*A,'omit the simplex moment denominator'),(s.gamma(1+1/m)/(m*m*(m+1)),'wrong total radial exponent')],['Set u=x+y and v=x/(x+y). The positive quadrant becomes u>0,0<v<1, with absolute Jacobian u.','The v integral is Beta(m,2)=1/[m(m+1)]. The radial integral is integral u^(m+1)e^-u^m du=Gamma(1+2/m)/m.'],[E(F.jacobian([uu,vv]).det(),-uu),E(s.integrate(vv**(m-1)*(1-vv),(vv,0,1)),1/(m*(m+1))),E(s.gamma((m+2)/m)/(m*m*(m+1)),A)],'positive-quadrant-sum-simplex-Gamma',['All integrands are nonnegative, so Tonelli permits separation.','The power substitution has Gamma shape 1+2/m>0.'],'simplex-ray-coordinate-Jacobian-and-Gamma-integral')
 add('lemniscate-petal-area','complex-lemniscate-geometry','polar-sectors-and-beta',lemniscate,'The complex inequality determines multiple petals; identifying their angular multiplicity and radial branch is necessary before integration.')
 add('squared-log-disk','harmonic-Parseval-disk','Fourier-orthogonality-and-generating-series',logsquare,'Squares a harmonic expansion, uses orthogonality, then evaluates a nontrivial weighted radial series with a dilogarithm.')
